from ub import *
UNIT = mkunit("u112",
 ["menyusun **email atau surat** dengan salam, isi, dan penutup",
  "membedakan gaya **santai** dan **resmi**",
  "memakai **ungkapan pembuka dan penutup** yang tepat",
  "menulis **subjek email** yang jelas dan singkat"],
 [intro("Email dan surat punya struktur tetap: **salam**, **pembuka**, **isi**, **penutup**, dan **nama**. Gaya bahasa berbeda untuk teman (santai) dan untuk guru, atasan, atau perusahaan (resmi). Unit ini melatih pola yang paling sering dipakai."),
  gram("1. Struktur email",
   table=[["Bagian", "Santai", "Resmi"],
          ["Subjek", "[[Weekend plan]]", "[[Request for a meeting on Friday]]"],
          ["Salam", "[[Hi Rani,]] / [[Dear Rani,]]", "[[Dear Mr. Adi,]] / [[Dear Sir or Madam,]]"],
          ["Pembuka", "[[How are you?]] / [[Thanks for your message.]]", "[[I am writing to ask about ...]]"],
          ["Isi", "kalimat pendek dan hangat", "kalimat sopan dan jelas"],
          ["Penutup", "[[See you soon!]] / [[Best wishes,]]", "[[I look forward to hearing from you.]]"],
          ["Tanda tangan", "[[Budi]]", "[[Yours sincerely, Budi Santoso]]"]],
   examples=[("[[Dear Mr. Adi, I am writing to ask about the English course. I look forward to hearing from you. Yours sincerely, Budi Santoso]]", "Yth. Bapak Adi, saya menulis untuk menanyakan kursus bahasa Inggris. Saya menunggu kabar dari Bapak. Hormat saya, Budi Santoso")]),
  gram("2. Ungkapan berguna",
   table=[["Tujuan", "Ungkapan"],
          ["Menyapa", "[[Hi]], [[Hello]], [[Dear ...]]"],
          ["Berterima kasih", "[[Thank you for your email.]]"],
          ["Menjelaskan tujuan", "[[I am writing to ...]] / [[I would like to ...]]"],
          ["Meminta", "[[Could you please send me ...?]]"],
          ["Menawarkan", "[[Let me know if you need help.]]"],
          ["Meminta maaf", "[[I am sorry for the delay.]]"],
          ["Menutup", "[[Best wishes]], [[Kind regards]], [[Yours sincerely]]"]]),
  gram("3. Penutup menurut keakraban",
   table=[["Hubungan", "Penutup", "Contoh"],
          ["Teman dekat", "[[Love]], [[See you soon]], [[Cheers]]", "[[See you soon, Dina]]"],
          ["Kenalan / rekan", "[[Best wishes]], [[Regards]]", "[[Best wishes, Tom]]"],
          ["Resmi (nama diketahui)", "[[Yours sincerely]]", "[[Yours sincerely, Budi]]"],
          ["Resmi (nama tidak diketahui)", "[[Yours faithfully]]", "[[Dear Sir or Madam ... Yours faithfully, Rani]]"]]),
  warn("Jangan campur gaya", text="Jangan memakai *Hey dude!* dalam email kepada guru, dan jangan memakai kalimat sangat kaku (*Hereby I inform you*) kepada teman. Sesuaikan bahasa dengan pembaca."),
  tip("Satu email, satu tujuan", text="Tulis tujuan email di kalimat kedua. Gunakan subjek yang singkat: *Question about homework*, bukan *Hello*."),
  summary(["Email: subjek, salam, pembuka, isi, penutup, nama.", "Santai: Hi, See you soon. Resmi: Dear Mr./Ms., Yours sincerely.", "Pembuka: [[I am writing to ...]]. Penutup: [[I look forward to hearing from you.]]", "Sesuaikan gaya dengan pembaca."])],
 [], [])
